'use strict';
/**
 * Builds the paste-in file for the stores' script manager from the two sources in docs/cart-brand/:
 *
 *   cart-brand.css + cart-brand.js  ->  cart-brand-entry.html   (the box CONTENT: <style> + <script>, ONE entry, pasted identically in all 5 stores)
 *                                         ->  preview-snippet.js         (the same CSS + JS for the browser console; previews in one tab only)
 *
 *   node scripts/build-cart-brand-entry.js            write both files
 *   node scripts/build-cart-brand-entry.js --check    exit 1 if a generated file is stale or a guard fails (PR check)
 *
 * Guards (the entry is pasted into a theme that renders every store page, so a leak would not stay on the cart screens):
 *   - every rule selector starts with a :has(...) cart scope (only :root, @import, @media and comments are exempt);
 *   - no "</style" / "</script" inside the content (it would end the box early); CSS braces balance; the JS parses;
 *   - no @import in the CSS (fonts are added by the JS, on /cart only) and the JS keeps its /cart font gate; the CSS declares the version (--mo-cart-skin).
 * Docs: docs/store-cart-ui.md.
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const DIR = path.join(__dirname, '..', 'docs', 'cart-brand');
const css = fs.readFileSync(path.join(DIR, 'cart-brand.css'), 'utf8');
const js = fs.readFileSync(path.join(DIR, 'cart-brand.js'), 'utf8');
const SCOPES = ['html body:has(#cart_list)', 'html body:has(.layer-add-cart-success)'];

// The pasted entry ships on every page of the store, so it is minified (the readable sources stay in the repo).
// CSS: comments out, whitespace collapsed, no space around { } ; , or after a colon (selectors never contain ": "). JS: only the leading block comment
// and full-line // comments are removed (no tokenizer, so nothing riskier).
const minCss = c => c.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').replace(/\s*([{};,])\s*/g, '$1').replace(/:\s+/g, ':').replace(/;}/g, '}').trim();
const minJs = j => j.replace(/^\s*\/\*[\s\S]*?\*\/\s*/, '').split('\n').filter(l => !/^\s*\/\//.test(l)).join('\n').trim();
const problems = [];
const version = (css.match(/--mo-cart-skin:\s*(v\d+)/) || [])[1];
if (!version) problems.push('the CSS must declare :root { --mo-cart-skin: vN } (the probe reads it to tell which stores have the entry)');

// selector scope: every line that opens or continues a selector list
css.replace(/\/\*[\s\S]*?\*\//g, m => ' '.repeat(m.length)).split('\n').forEach((raw, i) => {
  const line = raw.trim();
  if (!line || !/[,{]$/.test(line)) return;
  if (line.startsWith('@') || line.startsWith(':root') || line.startsWith('}') || /^[a-z-]+\s*:/i.test(line) && !line.startsWith('html')) return;
  if (!SCOPES.some(sc => line.startsWith(sc))) problems.push(`css line ${i + 1}: selector without a cart scope: ${line.slice(0, 90)}`);
});
const stripped = css.replace(/\/\*[\s\S]*?\*\//g, '');
if ((stripped.match(/{/g) || []).length !== (stripped.match(/}/g) || []).length) problems.push('css: unbalanced braces');
if (/@import/.test(stripped)) problems.push('css: no @import (it would load fonts on every store page; the JS adds the font link on /cart only)');
if (!/\/\^\\\/cart/.test(js)) problems.push('js: the /cart font gate is missing');
if (/<\/style/i.test(css)) problems.push('css contains </style');
if (/<\/script/i.test(js)) problems.push('js contains </script');
try { new vm.Script(js); } catch (e) { problems.push('js does not parse: ' + e.message); }

const CSS_MIN = minCss(css), JS_MIN = minJs(js);
if ((CSS_MIN.match(/{/g) || []).length !== (stripped.match(/{/g) || []).length) problems.push('css: minifying changed the number of rules');
try { new vm.Script(JS_MIN); } catch (e) { problems.push('minified js does not parse: ' + e.message); }
const entry = `<!-- MOMUTO cart skin ${version} — script-manager entry, box CONTENT (the platform adds its own start/end markers).
     GENERATED by scripts/build-cart-brand-entry.js from docs/cart-brand/cart-brand.css + cart-brand.js — do not edit here.
     Paste this whole file as ONE new entry named "MOMUTO cart skin ${version}" in EACH of the 5 stores (www, us, es, fr, it), identical.
     Restyles the /cart page and the "Added to cart" pop-up, and fixes two wrong FR/IT checkout labels.
     Every CSS rule is scoped with :has() to the cart page or the open pop-up; fonts load on /cart only; one body-children observer (FR/IT label fix) exists on other pages. To undo: disable or delete this entry. Docs: docs/cart-brand/README.md -->
<style>${CSS_MIN}</style>
<script>
${JS_MIN}
</script>
`;
const preview = `/* MOMUTO cart skin ${version} — PREVIEW ONLY. Paste this whole file into the browser console (F12 > Console) on a store /cart page,
 * e.g. us.momuto.com/cart. It styles THIS TAB ONLY; reload and it is gone.
 * GENERATED by scripts/build-cart-brand-entry.js from cart-brand.css + cart-brand.js. */
(function () {
  var st = document.createElement('style'); st.id = 'mo-cart-preview';
  st.textContent = ${JSON.stringify(CSS_MIN)};
  document.head.appendChild(st);
${JS_MIN}
})();
`;

const out = { 'cart-brand-entry.html': entry, 'preview-snippet.js': preview };
if (problems.length) { console.error('cart-brand guard FAILED:\n  - ' + problems.join('\n  - ')); process.exit(1); }
if (process.argv.includes('--check')) {
  const stale = Object.keys(out).filter(f => !fs.existsSync(path.join(DIR, f)) || fs.readFileSync(path.join(DIR, f), 'utf8') !== out[f]);
  if (stale.length) { console.error('stale generated file(s): ' + stale.join(', ') + '\nRun: node scripts/build-cart-brand-entry.js (and commit)'); process.exit(1); }
  console.log(`cart-brand: entry + preview are current (${version}, ${Buffer.byteLength(entry)} bytes).`);
} else {
  Object.entries(out).forEach(([f, c]) => fs.writeFileSync(path.join(DIR, f), c));
  console.log(`cart-brand: wrote cart-brand-entry.html (${Buffer.byteLength(entry)} bytes) and preview-snippet.js, version ${version}.`);
}
